def preserve_existing_activities(apps, schema_editor):
    Activity = apps.get_model("catalog", "Activity")
    Ledger = apps.get_model("catalog", "CoinTransaction")
    alias = schema_editor.connection.alias
    for activity in Activity.objects.using(alias).all().iterator():
        # The earlier service always used 10 coins/hour. Do not touch any balance or ledger entry.
        if activity.status == "pending" and activity.requested_hours is None:
            activity.status = "registered"
        else:
            activity.report_submitted_at = activity.reviewed_at or activity.created_at
        if activity.status == "approved":
            amount = (
                Ledger.objects.using(alias)
                .filter(activity_id=activity.pk)
                .values_list("amount", flat=True)
                .first()
            )
            activity.coins_awarded = (
                amount if amount is not None else int(activity.confirmed_hours * 10)
            )
        activity.save(
            using=alias,
            update_fields=["status", "report_submitted_at", "coins_awarded"],
        )


def restore_previous_statuses(apps, schema_editor):
    Activity = apps.get_model("catalog", "Activity")
    Activity.objects.using(schema_editor.connection.alias).filter(
        status="registered"
    ).update(status="pending")


